action.command:
curl -s "http://localhost:8080/supabase-events?limit=500" 2>/dev/null | node -e "
const data = JSON.parse(require('fs').readFileSync(0, 'utf-8'));
console.log('Total events returned:', data.count);
console.log('\nAll sources in response:', JSON.stringify(data.source_counts));
console.log('\nKulturhuset events in response:', data.events?.filter(e => e.source === 'kulturhuset').length || 0);

// Show earliest event dates
const sorted = [...data.events].sort((a, b) => a.date.localeCompare(b.date));
console.log('\nEarliest 5 events:');
sorted.slice(0, 5).forEach(e => console.log(' ', e.date, e.source, e.title.substring(0, 40)));
"

